import TaxProgress from "./TaxProgress";
import TaxResponse from "./TaxResponse";
import { Steps, TaxStep } from "./TaxStep";

export class TaxBehavior {
  /** Static steps and associated fields loaded from the database for the user to populate */
  steps: TaxStep[];
  progress: TaxProgress | undefined = undefined;

  constructor() {
    this.steps = [];
  }

  getStep(step: Steps): TaxStep | undefined {
    return this.steps.find((s) => s.step === step);
  }

  getStepIndex(step: Steps): number {
    return this.steps.findIndex((s) => s.step === step);
  }

  async loadYears(
    setYears: (years: number[]) => void,
    setError: (error: string | undefined) => void,
  ) {
    try {
      const response = await fetch("/api/progress/years");
      if (!response.ok) {
        throw new Error("Unable to load tax years.");
      }
      const data = (await response.json()) as number[];
      setYears(data);
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Unable to load tax years.",
      );
    }
  }

  async loadNames(
    year: number,
    setNames:  React.Dispatch<React.SetStateAction<string[]>>,
    setError: (error: string | undefined) => void,
  ) {
    try {
      const response = await fetch(`/api/progress/${year}/names`);
      if (!response.ok) {
        throw new Error("Unable to load saved progress names.");
      }
      const data = (await response.json()) as string[];
      setNames(data);
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : "Unable to load saved progress names.",
      );
    }
  }

  async loadAllNames(
    setNames:  React.Dispatch<React.SetStateAction<string[]>>,
    setError: (error: string | undefined) => void,
  ) {
    try {
      const response = await fetch(`/api/progress/names`);
      if (!response.ok) {
        throw new Error("Unable to load all names.");
      }
      const data = (await response.json()) as string[];
      setNames(data);
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : "Unable to load all names.",
      );
    }
  }

  async loadSteps(
    setCurrentStep: (step: Steps) => void,
    setError: (error: string | undefined) => void,
  ) {
    try {
      const response = await fetch("/api/steps");
      if (!response.ok) {
        throw new Error("Unable to load tax steps.");
      }
      const data = (await response.json()) as { steps: TaxStep[] };
      this.steps = [...data.steps];
      if (data.steps.length > 0) {
        setCurrentStep(data.steps[0].step as Steps);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong.");
    }
  }

  async resumeProgress(
    year: number,
    name: string,
    setCurrentStep: (step: Steps) => void,
    setResponses: (responses: TaxResponse[]) => void,
    setError: (error: string | undefined) => void,
    setLastSavedTime: (time: Date | undefined) => void,
  ) {
    if (this.steps.length === 0) {
      return;
    }
    try {
      const response = await fetch(`/api/progress/${year}/${name}`);
      if (!response.ok) {
        if (response.status === 404) {
          return;
        }
        throw new Error("Unable to load saved progress.");
      }
      const saved = (await response.json()) as TaxProgress;
      if (saved.year !== year) {
        return;
      }
      setCurrentStep(saved.currentStep as Steps);
      setResponses(saved.responses.map((r) => new TaxResponse(r.id, r.value)));
      setLastSavedTime(new Date(saved.updatedAt));
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Unable to load saved progress.",
      );
    }
  }

  async saveProgress(
    year: number,
    name: string,
    currentStep: Steps | undefined,
    responses: TaxResponse[],
    setError: (error: string | undefined) => void,
    setIsSaving: (saving: boolean) => void,
    setToastMessage: (message: string | undefined) => void,
    setLastSavedTime: (time: Date | undefined) => void,
  ) {
    if (!currentStep) {
      return;
    }

    try {
      setIsSaving(true);
      const payload: Partial<TaxProgress> = {
        year,
        name,
        currentStep: this.getStep(currentStep)?.step,
        responses,
      };
      const response = await fetch("/api/progress/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!response.ok) {
        throw new Error("Unable to save progress.");
      }
      const saved = (await response.json()) as TaxProgress;
      const savedTime = new Date(saved.updatedAt);
      setLastSavedTime(savedTime);
      setToastMessage(`Saved at ${savedTime.toLocaleTimeString()}`);
      setTimeout(() => setToastMessage(undefined), 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to save progress.");
    } finally {
      setIsSaving(false);
    }
  }

  async deleteProgress(
    year: number,
    name: string,
    setIsDeleting: (loading: boolean) => void,
    setToastMessage: (message: string | undefined) => void,
  ) {
    try {
      if (!this.progress) {
        return;
      }
      setIsDeleting(true);
      const response = await fetch(`/api/progress/${year}/${name}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error("Unable to delete progress.");
      }
      setToastMessage("Progress deleted.");
      setTimeout(() => setToastMessage(undefined), 3000);
    } catch (err) {
      setToastMessage("Failed to delete progress.");
    } finally {
      setIsDeleting(false);
    }
  }
}

import { useCallback, useMemo } from "react";
import type { Steps } from "../DataModel/TaxStep";
import type { TaxBehavior } from "../DataModel/TaxBehavior";

interface BackButtonProps {
  readonly taxBehavior: TaxBehavior;
  readonly currentStep: Steps;
  readonly setCurrentStep: (step: Steps) => void;
}

export default function BackButton(props: BackButtonProps) {
  const { taxBehavior, currentStep, setCurrentStep } = props;

  const currentIndex = useMemo(
    () => taxBehavior.getStepIndex(currentStep),
    [currentStep],
  );

  const handleBack = useCallback(() => {
    const nextIndex = Math.max(currentIndex - 1, 0);
    const nextStep = taxBehavior.steps[nextIndex];
    setCurrentStep(nextStep.step);
  }, [currentIndex, taxBehavior.steps, setCurrentStep]);

  return (
    <button
      className="ghost"
      onClick={handleBack}
      disabled={currentIndex === 0}
    >
      Back
    </button>
  );
}

import { useCallback } from "react";
import type { TaxBehavior } from "../DataModel/TaxBehavior";
import type { Steps } from "../DataModel/TaxStep";

interface ClearButtonProps {
  readonly currentStep: Steps;
  readonly taxBehavior: TaxBehavior;
  readonly isSaving: boolean;
  readonly isDeleting: boolean;
  readonly lastSavedTime: Date | undefined;
  readonly year: number;
  readonly name: string;
  readonly setIsDeleting: React.Dispatch<React.SetStateAction<boolean>>;
  readonly setToastMessage: React.Dispatch<
    React.SetStateAction<string | undefined>
  >;
  readonly setLastSavedTime: React.Dispatch<
    React.SetStateAction<Date | undefined>
  >;
}

export default function DeleteButton(props: ClearButtonProps) {
  const {
    currentStep,
    taxBehavior,
    isSaving,
    isDeleting,
    lastSavedTime,
    year,
    name,
    setIsDeleting,
    setToastMessage,
    setLastSavedTime,
  } = props;

  //#region useCallback
  const handleDelete = useCallback(async () => {
    const confirmed = window.confirm(
      "Are you sure you want to delete all progress? This cannot be undone.",
    );
    if (confirmed) {
      taxBehavior.deleteProgress(year, name, setIsDeleting, setToastMessage);
      setLastSavedTime(undefined);
    }
  }, [currentStep, year, name]);
  //#endregion useCallback

  return (
    <button
      className="ghost"
      onClick={handleDelete}
      disabled={isSaving || isDeleting || !lastSavedTime}
    >
      {isDeleting ? "Deleting..." : "Delete progress"}
    </button>
  );
}

import { useCallback } from "react";
import TaxResponse from "../DataModel/TaxResponse";
import type { TaxStep } from "../DataModel/TaxStep";
import EntryField from "./EntryField";

interface FormFieldsProps {
  step: TaxStep;
  responses: TaxResponse[];
  setResponses: React.Dispatch<React.SetStateAction<TaxResponse[]>>;
}

export default function FormFields(props: FormFieldsProps) {
  const { step, responses, setResponses } = props;

  //#region useCallback
  const handleResponseChange = useCallback((fieldId: string, value: string) => {
    setResponses((prev) => {
      const existingIndex = prev.findIndex((r) => r.id === fieldId);
      if (existingIndex !== -1) {
        // Update existing response
        const updated = [...prev];
        updated[existingIndex] = new TaxResponse(fieldId, value);
        return updated;
      } else {
        // Add new response
        return [...prev, new TaxResponse(fieldId, value)];
      }
    });
  }, []);
  //#endregion useCallback

  return (
    <div className="fields">
      {step.fields.map((field) => (
        <label key={field.id} className="field">
          <span>{field.label}</span>
          <EntryField
            field={field}
            responses={responses}
            onResponseChange={handleResponseChange}
          />
          {field.helperText ? <small>{field.helperText}</small> : null}
        </label>
      ))}
    </div>
  );
}

